<?php
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/functions.php';zorunlu_rol('admin','yonetici');

function turnuva_etiket($sira){$sira=(int)$sira-1;$etiket='';do{$etiket=chr(65+($sira%26)).$etiket;$sira=intdiv($sira,26)-1;}while($sira>=0);return $etiket;}
function turnuva_agacini_temizle($pdo,$turnuvaId){
    $q=$pdo->prepare('SELECT id FROM turnuva_maclari WHERE turnuva_id=?');$q->execute([$turnuvaId]);$maclar=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));
    if($maclar){$yer=implode(',',array_fill(0,count($maclar),'?'));$pdo->prepare("DELETE FROM turnuva_sporcu_set_atislari WHERE turnuva_mac_id IN ($yer)")->execute($maclar);$pdo->prepare("DELETE FROM turnuva_mac_setleri WHERE turnuva_mac_id IN ($yer)")->execute($maclar);$pdo->prepare("DELETE FROM esitlik_bozma_atislari WHERE turnuva_mac_id IN ($yer)")->execute($maclar);}
    $pdo->prepare('DELETE FROM turnuva_maclari WHERE turnuva_id=?')->execute([$turnuvaId]);$pdo->prepare('DELETE FROM turnuva_eslesmeleri WHERE turnuva_id=?')->execute([$turnuvaId]);$pdo->prepare("UPDATE turnuvalar SET durum='taslak' WHERE id=?")->execute([$turnuvaId]);
}
function turnuva_agacini_kur($pdo,$turnuva,$hedefler){
    $turnuvaId=(int)$turnuva['id'];$kontenjan=(int)$turnuva['kontenjan'];
    if(count($hedefler)!==$kontenjan||count(array_unique($hedefler))!==$kontenjan)throw new RuntimeException('Kontenjan kadar, birbirinden farklı katılımcı seçmelisiniz.');
    turnuva_agacini_temizle($pdo,$turnuvaId);$pdo->prepare('DELETE FROM turnuva_katilimcilari WHERE turnuva_id=?')->execute([$turnuvaId]);
    $katilimciEkle=$pdo->prepare('INSERT INTO turnuva_katilimcilari(turnuva_id,hedef_id,sira) VALUES(?,?,?)');foreach($hedefler as $sira=>$hedef)$katilimciEkle->execute([$turnuvaId,$hedef,$sira+1]);
    $q=$pdo->prepare('SELECT id,hedef_id FROM turnuva_katilimcilari WHERE turnuva_id=? ORDER BY sira');$q->execute([$turnuvaId]);$katilimcilar=$q->fetchAll();
    $esEkle=$pdo->prepare('INSERT INTO turnuva_eslesmeleri(turnuva_id,tur_no,eslesme_no,katilimci1_id,katilimci2_id) VALUES(?,?,?,?,?)');$macEkle=$pdo->prepare('INSERT INTO turnuva_maclari(turnuva_id,eslesme_id,katilimci1_id,katilimci2_id,tur_no) VALUES(?,?,?,?,?)');
    $eslesmeNo=1;for($i=0;$i<$kontenjan;$i+=4){foreach([[$i,$i+2],[$i+1,$i+3]] as [$a,$b]){$esEkle->execute([$turnuvaId,1,$eslesmeNo++,$katilimcilar[$a]['id'],$katilimcilar[$b]['id']]);$esId=(int)$pdo->lastInsertId();$macEkle->execute([$turnuvaId,$esId,$katilimcilar[$a]['hedef_id'],$katilimcilar[$b]['hedef_id'],1]);}}
    $turSayisi=(int)round(log($kontenjan,2));for($tur=2;$tur<=$turSayisi;$tur++){for($no=1;$no<=$kontenjan/(2**$tur);$no++){$esEkle->execute([$turnuvaId,$tur,$no,null,null]);$esId=(int)$pdo->lastInsertId();$macEkle->execute([$turnuvaId,$esId,null,null,$tur]);}}
    $pdo->prepare("UPDATE turnuvalar SET durum='eslesme_hazir' WHERE id=?")->execute([$turnuvaId]);
}

$id=(int)($_GET['id']??$_POST['turnuva_id']??0);$sayfaIslem=$_GET['islem']??'';
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        if(!csrf_check($_POST['csrf']??''))throw new RuntimeException('Güvenlik doğrulaması başarısız.');$islem=$_POST['islem']??'';
        if($islem==='turnuva_olustur'){
            $ad=trim($_POST['turnuva_adi']??'');$tur=$_POST['tur']??'takim';$kontenjan=(int)($_POST['kontenjan']??16);$sezonId=(int)($_POST['sezon_id']??0);
            if($ad===''||!in_array($tur,['takim','bireysel'],true)||!in_array($kontenjan,[16,32],true)||!$sezonId)throw new RuntimeException('Turnuva adı, türü, sezonu ve kontenjanı seçin.');
            $pdo->prepare('INSERT INTO turnuvalar(turnuva_adi,tur,kontenjan,sezon_id,aciklama) VALUES(?,?,?,?,?)')->execute([$ad,$tur,$kontenjan,$sezonId,trim($_POST['aciklama']??'')]);flash_set('basari','Turnuva oluşturuldu. Ağaç Oluştur ile katılımcıları seçebilirsiniz.');
        }elseif($islem==='agac_olustur'){
            $q=$pdo->prepare('SELECT * FROM turnuvalar WHERE id=?');$q->execute([$id]);$turnuva=$q->fetch();if(!$turnuva)throw new RuntimeException('Turnuva bulunamadı.');
            $hedefler=array_values(array_filter(array_map('intval',$_POST['katilimci']??[])));$pdo->beginTransaction();turnuva_agacini_kur($pdo,$turnuva,$hedefler);$pdo->commit();flash_set('basari','A–C ve B–D sıralamasına göre turnuva ağacı oluşturuldu.');
        }elseif($islem==='agaci_temizle'){
            $pdo->beginTransaction();turnuva_agacini_temizle($pdo,$id);$pdo->prepare('DELETE FROM turnuva_katilimcilari WHERE turnuva_id=?')->execute([$id]);$pdo->commit();flash_set('basari','Turnuva ağacı ve katılımcı yerleşimi temizlendi.');
        }elseif($islem==='turnuva_guncelle'){
            $ad=trim($_POST['turnuva_adi']??'');$sezonId=(int)($_POST['sezon_id']??0);if(!$id||$ad===''||!$sezonId)throw new RuntimeException('Turnuva adı ve sezon zorunludur.');$pdo->prepare('UPDATE turnuvalar SET turnuva_adi=?,sezon_id=?,aciklama=? WHERE id=?')->execute([$ad,$sezonId,trim($_POST['aciklama']??''),$id]);flash_set('basari','Turnuva bilgileri güncellendi.');
        }elseif($islem==='turnuva_sil'){
            $pdo->beginTransaction();turnuva_agacini_temizle($pdo,$id);$pdo->prepare('DELETE FROM turnuva_katilimcilari WHERE turnuva_id=?')->execute([$id]);$pdo->prepare('DELETE FROM turnuvalar WHERE id=?')->execute([$id]);$pdo->commit();flash_set('basari','Turnuva silindi.');
        }
    }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash_set('hata',$e->getMessage());}
    redirect(BASE_URL.'/admin/turnuvalar.php');
}

$sezonlar=$pdo->query("SELECT * FROM sezonlar WHERE durum='aktif' ORDER BY sezon_adi DESC")->fetchAll();$secili=null;$adaylar=[];
if($id&&in_array($sayfaIslem,['agac','duzenle'],true)){$q=$pdo->prepare('SELECT * FROM turnuvalar WHERE id=?');$q->execute([$id]);$secili=$q->fetch();if(!$secili){flash_set('hata','Turnuva bulunamadı.');redirect(BASE_URL.'/admin/turnuvalar.php');}if($sayfaIslem==='agac'){$adaylar=$secili['tur']==='takim'?$pdo->query('SELECT id,takim_adi ad FROM takimlar ORDER BY takim_adi')->fetchAll():$pdo->query("SELECT id,CONCAT(ad,' ',soyad) ad FROM sporcular ORDER BY ad,soyad")->fetchAll();}}
$liste=$pdo->query('SELECT t.*,COUNT(k.id) katilimci FROM turnuvalar t LEFT JOIN turnuva_katilimcilari k ON k.turnuva_id=t.id GROUP BY t.id ORDER BY t.created_at DESC')->fetchAll();
ob_start();
?>
