<section class="card"><div class="card-head"><h2><?= $sayfaIslem==='duzenle'?'Turnuvayı Düzenle':'Yeni Turnuva' ?></h2></div>
<?php if($sayfaIslem==='duzenle'&&$secili): ?><form method="post" class="form"><?= csrf_field() ?><input type="hidden" name="islem" value="turnuva_guncelle"><input type="hidden" name="turnuva_id" value="<?= $id ?>"><div class="grid-2"><label>Turnuva adı *<input name="turnuva_adi" required value="<?= e($secili['turnuva_adi']) ?>"></label><label>Tür<input disabled value="<?= $secili['tur']==='takim'?'Takım Turnuvası':'Bireysel Turnuva' ?>"></label></div><div class="grid-2"><label>Katılımcı sayısı<input disabled value="<?= (int)$secili['kontenjan'] ?>"></label><label>Sezon *<select name="sezon_id"><?php foreach($sezonlar as $s): ?><option value="<?= (int)$s['id'] ?>" <?= (int)$secili['sezon_id']===(int)$s['id']?'selected':'' ?>><?= e($s['sezon_adi']) ?></option><?php endforeach; ?></select></label></div><label>Açıklama<textarea name="aciklama"><?= e($secili['aciklama']) ?></textarea></label><button class="btn btn-primary">Güncelle</button> <a class="btn btn-outline" href="<?= BASE_URL ?>/admin/turnuvalar.php">Vazgeç</a></form>
<?php else: ?><p class="muted">Turnuvayı oluşturun; katılımcıları daha sonra Ağaç Oluştur işleminden sıralı olarak yerleştirin.</p><form method="post" class="form"><?= csrf_field() ?><input type="hidden" name="islem" value="turnuva_olustur"><div class="grid-2"><label>Turnuva adı *<input name="turnuva_adi" required placeholder="Geleneksel Okçuluk Turnuvası"></label><label>Tür *<select name="tur"><option value="takim">Takım Turnuvası</option><option value="bireysel">Bireysel Turnuva</option></select></label></div><div class="grid-2"><label>Katılımcı sayısı *<select name="kontenjan"><option value="16">16 katılımcı</option><option value="32">32 katılımcı</option></select></label><label>Sezon *<select name="sezon_id"><?php foreach($sezonlar as $s): ?><option value="<?= (int)$s['id'] ?>"><?= e($s['sezon_adi']) ?></option><?php endforeach; ?></select></label></div><label>Açıklama<textarea name="aciklama"></textarea></label><button class="btn btn-primary">Turnuvayı Oluştur</button></form><?php endif; ?>
</section>
<section class="card"><div class="card-head"><h2>Oluşturulan Turnuvalar</h2><span class="badge"><?= count($liste) ?> turnuva</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Turnuva</th><th>Tür</th><th>Katılımcı</th><th>İşlem</th></tr></thead><tbody><?php foreach($liste as $x): ?><tr><td><?= e($x['turnuva_adi']) ?></td><td><?= $x['tur']==='takim'?'Takım':'Bireysel' ?></td><td><?= (int)$x['katilimci'].' / '.(int)$x['kontenjan'] ?></td><td class="actions"><a class="btn btn-sm btn-primary" href="<?= BASE_URL ?>/admin/turnuvalar.php?islem=agac&id=<?= (int)$x['id'] ?>">Ağaç Oluştur</a><form method="post" class="inline-form" onsubmit="return confirm('Bu turnuvanın ağacı ve katılımcı yerleşimi temizlensin mi?')"><?= csrf_field() ?><input type="hidden" name="islem" value="agaci_temizle"><input type="hidden" name="turnuva_id" value="<?= (int)$x['id'] ?>"><button class="btn btn-sm">Ağacı Temizle</button></form><a class="btn btn-sm" href="<?= BASE_URL ?>/admin/turnuvalar.php?islem=duzenle&id=<?= (int)$x['id'] ?>">Düzenle</a><form method="post" class="inline-form" onsubmit="return confirm('Turnuva tamamen silinsin mi?')"><?= csrf_field() ?><input type="hidden" name="islem" value="turnuva_sil"><input type="hidden" name="turnuva_id" value="<?= (int)$x['id'] ?>"><button class="btn btn-sm btn-danger">Sil</button></form></td></tr><?php endforeach; ?><?php if(!$liste): ?><tr><td colspan="4" class="muted">Henüz turnuva oluşturulmamış.</td></tr><?php endif; ?></tbody></table></div></section>
</div>

<?php if($sayfaIslem==='agac'&&$secili): ?><section class="card" style="margin-top:16px"><div class="card-head"><h2><?= e($secili['turnuva_adi']) ?> · Katılımcı Yerleşimi</h2><span class="badge"><?= (int)$secili['kontenjan'] ?> <?= $secili['tur']==='takim'?'takım':'sporcu' ?></span></div><p class="muted">Katılımcıları A, B, C, D… sırasıyla seçin. Aynı katılımcı ikinci kez seçilemez; A–C ve B–D eşleşmeleri otomatik kurulur.</p><form method="post" class="form" id="katilimci-formu"><?= csrf_field() ?><input type="hidden" name="islem" value="agac_olustur"><input type="hidden" name="turnuva_id" value="<?= $id ?>"><div class="grid-2"><?php for($i=0;$i<(int)$secili['kontenjan'];$i++): ?><label><?= turnuva_etiket($i+1) ?><select name="katilimci[]" class="katilimci-sec" required><option value="">Seçin</option><?php foreach($adaylar as $a): ?><option value="<?= (int)$a['id'] ?>"><?= e($a['ad']) ?></option><?php endforeach; ?></select></label><?php endfor; ?></div><div class="form-actions"><button class="btn btn-primary">Ağacı Oluştur</button><a class="btn btn-outline" href="<?= BASE_URL ?>/admin/turnuvalar.php">Vazgeç</a></div></form></section><script>document.querySelectorAll('.katilimci-sec').forEach(function(s){s.addEventListener('change',function(){var secilen=[].map.call(document.querySelectorAll('.katilimci-sec'),function(x){return x.value}).filter(Boolean);document.querySelectorAll('.katilimci-sec option').forEach(function(o){o.disabled=o.value!==''&&secilen.includes(o.value)&&o.parentElement.value!==o.value;});});});</script><?php endif; ?>
